#include <iostream>
#include <string>
#include <vector>

int total(const std::vector<int>& sessions)
{
    int result{};
    for (int pages : sessions) result += pages;
    return result;
}

void set_completed(int& completed, int value)
{
    completed = value;
}

std::string make_label(int completed)
{
    return "Completed: " + std::to_string(completed);
}

int main()
{
    const std::vector<int> sessions{4, 6, 5};
    int completed{};
    set_completed(completed, total(sessions));
    const std::string label = make_label(completed);
    std::cout << label << '\n';
}
